CREATE TABLE "fc_approval_policies" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "action" TEXT NOT NULL, "threshold" DECIMAL(38,18) NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "forbid_self_approval" BOOLEAN NOT NULL, "required_authority" TEXT NOT NULL, CONSTRAINT "fc_approval_policies_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "fc_approval_policies_company_id_action_key" ON "fc_approval_policies"("company_id", "action");
