CREATE TABLE "fc_approval_requests" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "branch_id" TEXT, "action" TEXT NOT NULL, "source_type" TEXT NOT NULL, "source_id" TEXT NOT NULL, "requester_actor_id" TEXT NOT NULL, "amount" DECIMAL(38,18) NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "policy_id" TEXT NOT NULL, "requested_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "fc_approval_requests_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "fc_approval_requests_company_id_source_type_source_id_key" ON "fc_approval_requests"("company_id", "source_type", "source_id"); CREATE UNIQUE INDEX "fc_approval_requests_company_id_id_key" ON "fc_approval_requests"("company_id", "id");
ALTER TABLE "fc_approval_requests" ADD CONSTRAINT "fc_approval_requests_company_id_policy_id_fkey" FOREIGN KEY ("company_id", "policy_id") REFERENCES "fc_approval_policies"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
