CREATE TABLE "fc_reconciliation_issues" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "run_id" TEXT NOT NULL, "evidence_key" TEXT NOT NULL, "source_amount" DECIMAL(38,18) NOT NULL, "ledger_amount" DECIMAL(38,18) NOT NULL, "difference" DECIMAL(38,18) NOT NULL, "detail" TEXT NOT NULL, "resolved_at" TIMESTAMP(3), "resolution_reference" TEXT, CONSTRAINT "fc_reconciliation_issues_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "fc_reconciliation_issues_run_id_evidence_key_key" ON "fc_reconciliation_issues"("run_id", "evidence_key"); CREATE INDEX "fc_reconciliation_issues_company_id_resolved_at_idx" ON "fc_reconciliation_issues"("company_id", "resolved_at"); ALTER TABLE "fc_reconciliation_issues" ADD CONSTRAINT "fc_reconciliation_issues_company_id_run_id_fkey" FOREIGN KEY ("company_id", "run_id") REFERENCES "fc_reconciliation_runs"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "fc_close_readiness_runs" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "branch_id" TEXT, "correlation_id" TEXT NOT NULL, "fingerprint" TEXT NOT NULL, "ready" BOOLEAN NOT NULL, "blockers" JSONB NOT NULL, "warnings" JSONB NOT NULL, "evaluated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "fc_close_readiness_runs_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "fc_close_readiness_runs_company_id_correlation_id_key" ON "fc_close_readiness_runs"("company_id", "correlation_id");
